#include "darc_internal.h"
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <dirent.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>

typedef struct {DarcRhMap map;DarcCid *order;size_t n,cap;} Reach;
typedef struct {uint64_t refs,objects,healthy,corrupt,missing,repaired,unrecoverable,parity_ok,parity_bad,index_bad,history_missing;bool degraded;} VStat;
typedef struct {DarcCid cid;DarcSnapshotObj s;} VSnap;
typedef struct {VSnap*v;size_t n,cap;} VSnapVec;
static void reach_free(Reach*r){darc_rh_free(&r->map);free(r->order);memset(r,0,sizeof*r);}
static int reach_init(Reach*r){memset(r,0,sizeof*r);return darc_rh_init(&r->map,256);}
static int reach_add(Reach*r,const DarcCid*c,uint8_t type){if(darc_rh_get(&r->map,c))return 0;DarcRhEnt e;memset(&e,0,sizeof e);e.cid=*c;e.type=type;if(darc_rh_put(&r->map,&e))return -1;if(r->n==r->cap){size_t nc=r->cap?r->cap*2:256;DarcCid*v=darc_realloc(r->order,nc*sizeof*v);if(!v)return -1;r->order=v;r->cap=nc;}r->order[r->n++]=*c;return 0;}
static int reach_has(Reach*r,const DarcCid*c){return darc_rh_get(&r->map,c)!=NULL;}
static void snaps_free(VSnapVec*s){if(s->v)for(size_t i=0;i<s->n;i++)darc_snapshot_free(&s->v[i].s);free(s->v);memset(s,0,sizeof*s);}
static int snaps_push(VSnapVec*s,const DarcCid*c,DarcSnapshotObj*o){if(s->n==s->cap){size_t nc=s->cap?s->cap*2:16;VSnap*v=darc_realloc(s->v,nc*sizeof*v);if(!v)return -1;s->v=v;s->cap=nc;}s->v[s->n].cid=*c;s->v[s->n].s=*o;memset(o,0,sizeof*o);s->n++;return 0;}
static int read_refs(const char*repo,VSnapVec*out,VStat*vs){
 memset(out,0,sizeof*out);int rc=DARC_E_IO;char*dir=darc_path_join(repo,"refs/snapshots");if(!dir)return DARC_E_IO;
 DIR*d=opendir(dir);if(!d){free(dir);return DARC_E_IO;}struct dirent*de;
 while((de=readdir(d))){
  if(de->d_name[0]=='.')continue;
  if(strlen(de->d_name)!=64){rc=DARC_E_CORRUPT;goto fail_dir;}
  DarcCid c;if(darc_hex_cid(de->d_name,&c)){rc=DARC_E_CORRUPT;goto fail_dir;}
  char*p=darc_path_join(dir,de->d_name);DarcBuf b;memset(&b,0,sizeof b);
  if(!p||darc_read_file(p,&b,128)){free(p);rc=DARC_E_CORRUPT;goto fail_dir;}free(p);
  if(b.len!=65||memcmp(b.data,de->d_name,64)||b.data[64]!='\n'){darc_buf_free(&b);rc=DARC_E_CORRUPT;goto fail_dir;}darc_buf_free(&b);
  DarcObject o;rc=darc_object_load(repo,&c,&o,1);if(rc){char hx[65];darc_cid_hex(&c,hx);darc_error(rc==DARC_E_UNSUPPORTED?DARC_E_UNSUPPORTED:DARC_E_CORRUPT,rc==DARC_E_UNSUPPORTED?"E_UNSUPPORTED_OBJECT":"E_REF_TARGET","snapshot ref target %s is missing/corrupt",hx);rc=rc==DARC_E_UNSUPPORTED?DARC_E_UNSUPPORTED:DARC_E_CORRUPT;goto fail_dir;}
  if(o.type!=OBJ_SNAPSHOT){darc_object_free(&o);rc=DARC_E_CORRUPT;goto fail_dir;}
  DarcSnapshotObj snap;if(darc_snapshot_parse(o.payload.data,o.payload.len,&snap)){darc_object_free(&o);rc=DARC_E_CORRUPT;goto fail_dir;}darc_object_free(&o);
  if(snaps_push(out,&c,&snap)){darc_snapshot_free(&snap);rc=DARC_E_IO;goto fail_dir;}if(vs)vs->refs++;
 }
 closedir(d);d=NULL;free(dir);dir=NULL;
 /* HEAD must be empty or point at one of the published refs. */
 char*hp=darc_path_join(repo,"HEAD");if(!hp){rc=DARC_E_IO;goto fail;}DarcBuf hb;memset(&hb,0,sizeof hb);
 if(darc_read_file(hp,&hb,128)){free(hp);rc=DARC_E_CORRUPT;goto fail;}free(hp);
 if(hb.len){if(hb.len!=65||hb.data[64]!='\n'){darc_buf_free(&hb);rc=DARC_E_CORRUPT;goto fail;}char h[65];memcpy(h,hb.data,64);h[64]=0;DarcCid hc;if(darc_hex_cid(h,&hc)){darc_buf_free(&hb);rc=DARC_E_CORRUPT;goto fail;}bool found=false;for(size_t i=0;i<out->n;i++)if(darc_cid_eq(&out->v[i].cid,&hc)){found=true;break;}if(!found){darc_buf_free(&hb);rc=DARC_E_CORRUPT;goto fail;}}
 darc_buf_free(&hb);return 0;
fail_dir:if(d)closedir(d);free(dir);
fail:snaps_free(out);return rc;
}
static int collect_tree(const char*repo,const DarcCid*tc,Reach*r,size_t depth){if(depth>4096)return DARC_E_CORRUPT;if(reach_add(r,tc,OBJ_TREE))return DARC_E_IO;DarcObject o;int rc=darc_object_load(repo,tc,&o,1);if(rc){char hx[65];darc_cid_hex(tc,hx);darc_error(rc==DARC_E_UNSUPPORTED?DARC_E_UNSUPPORTED:DARC_E_CORRUPT,rc==DARC_E_UNSUPPORTED?"E_UNSUPPORTED_OBJECT":"E_MERKLE_OBJECT","TREE object %s cannot be loaded",hx);return rc;}if(o.type!=OBJ_TREE){char hx[65];darc_cid_hex(tc,hx);darc_object_free(&o);darc_error(DARC_E_CORRUPT,"E_MERKLE_OBJECT","TREE reference %s resolves to wrong object type",hx);return DARC_E_CORRUPT;}DarcTreeObj t;if(darc_tree_parse(o.payload.data,o.payload.len,&t)){darc_object_free(&o);return DARC_E_CORRUPT;}darc_object_free(&o);for(size_t i=0;i<t.n;i++){DarcTreeEnt*e=&t.e[i];if(e->type==1){if(reach_add(r,&e->cid,OBJ_FILE)){rc=DARC_E_IO;break;}DarcObject fo;rc=darc_object_load(repo,&e->cid,&fo,1);if(rc){char hx[65];darc_cid_hex(&e->cid,hx);darc_error(rc==DARC_E_UNSUPPORTED?DARC_E_UNSUPPORTED:DARC_E_CORRUPT,rc==DARC_E_UNSUPPORTED?"E_UNSUPPORTED_OBJECT":"E_MERKLE_CHILD","FILE child %s referenced by TREE is missing/corrupt",hx);break;}if(fo.type!=OBJ_FILE){char hx[65];darc_cid_hex(&e->cid,hx);darc_object_free(&fo);darc_error(DARC_E_CORRUPT,"E_MERKLE_CHILD","TREE child %s has wrong type",hx);rc=DARC_E_CORRUPT;break;}DarcFileObj f;if(darc_file_parse(fo.payload.data,fo.payload.len,&f)){darc_object_free(&fo);rc=DARC_E_CORRUPT;break;}darc_object_free(&fo);for(size_t j=0;j<f.chunk_n;j++)if(reach_add(r,&f.chunks[j].cid,OBJ_CHUNK)){rc=DARC_E_IO;break;}darc_file_free(&f);if(rc)break;}else if(e->type==2){rc=collect_tree(repo,&e->cid,r,depth+1);if(rc)break;}}darc_tree_free(&t);return rc;}
static int build_reach(const char*repo,const VSnapVec*s,Reach*r){if(reach_init(r))return DARC_E_IO;for(size_t i=0;i<s->n;i++){if(reach_add(r,&s->v[i].cid,OBJ_SNAPSHOT)){reach_free(r);return DARC_E_IO;}int rc=collect_tree(repo,&s->v[i].s.root,r,0);if(rc){reach_free(r);return rc;}}return 0;}
static int verify_file_bytes(const char*repo,const DarcCid*fc,VStat*vs,bool repair){DarcObject o;int rc=darc_object_load(repo,fc,&o,1);if(rc)return rc;if(o.type!=OBJ_FILE){darc_object_free(&o);return DARC_E_CORRUPT;}DarcFileObj f;if(darc_file_parse(o.payload.data,o.payload.len,&f)){darc_object_free(&o);return DARC_E_CORRUPT;}darc_object_free(&o);DarcSha256 sh;darc_sha256_init(&sh);uint64_t n=0;for(size_t i=0;i<f.chunk_n;i++){DarcObject co;int direct=darc_object_load(repo,&f.chunks[i].cid,&co,1);if(!direct){if(co.type!=OBJ_CHUNK||co.payload.len!=f.chunks[i].len){darc_object_free(&co);darc_file_free(&f);return DARC_E_CORRUPT;}darc_sha256_update(&sh,co.payload.data,co.payload.len);n+=co.payload.len;darc_object_free(&co);}else{DarcBuf b;bool rec=false;rc=darc_chunk_read_or_recover(repo,&f.chunks[i].cid,&b,repair,&rec);if(rc){char hx[65];darc_cid_hex(&f.chunks[i].cid,hx);vs->unrecoverable++;darc_error(DARC_E_UNRECOVERABLE,"E_UNRECOVERABLE","chunk %s is missing/corrupt and cannot be reconstructed",hx);darc_file_free(&f);return DARC_E_UNRECOVERABLE;}if(rec){char hx[65];darc_cid_hex(&f.chunks[i].cid,hx);vs->degraded=true;darc_error(DARC_E_CORRUPT,"E_CHUNK_RECOVERABLE","chunk %s required parity reconstruction%s",hx,repair?" and was repaired":"");if(repair)vs->repaired++;else vs->missing++;}if(b.len!=f.chunks[i].len){darc_buf_free(&b);darc_file_free(&f);return DARC_E_CORRUPT;}darc_sha256_update(&sh,b.data,b.len);n+=b.len;darc_buf_free(&b);}}
 uint8_t h[32];darc_sha256_final(&sh,h);rc=(n==f.logical_size&&!memcmp(h,f.digest,32))?0:DARC_E_CORRUPT;darc_file_free(&f);return rc;}
static int verify_snapshot_totals(const char*repo,const VSnap*s,VStat*vs,bool repair){DarcFlatTree t;int rc=darc_flatten_snapshot(repo,&s->s,&t);if(rc)return rc;uint64_t files=0,dirs=0,syms=0,hls=0,logical=0;Reach chunks;if(reach_init(&chunks)){darc_flat_free(&t);return DARC_E_IO;}Reach seenfiles;if(reach_init(&seenfiles)){reach_free(&chunks);darc_flat_free(&t);return DARC_E_IO;}for(size_t i=0;i<t.n;i++){DarcFlatEnt*e=&t.v[i];if(e->type==1){files++;logical+=e->logical_size;if(!reach_has(&seenfiles,&e->cid)){reach_add(&seenfiles,&e->cid,OBJ_FILE);rc=verify_file_bytes(repo,&e->cid,vs,repair);if(rc)break;DarcObject o;if(darc_object_load(repo,&e->cid,&o,1)){rc=DARC_E_CORRUPT;break;}DarcFileObj f;if(darc_file_parse(o.payload.data,o.payload.len,&f)){darc_object_free(&o);rc=DARC_E_CORRUPT;break;}darc_object_free(&o);for(size_t j=0;j<f.chunk_n;j++)reach_add(&chunks,&f.chunks[j].cid,OBJ_CHUNK);darc_file_free(&f);}}else if(e->type==2)dirs++;else if(e->type==3)syms++;else if(e->type==4)hls++;}if(!rc&&(files!=s->s.files||dirs!=s->s.dirs||syms!=s->s.symlinks||hls!=s->s.hardlinks||logical!=s->s.logical_bytes||chunks.n!=s->s.unique_chunks))rc=DARC_E_CORRUPT;reach_free(&chunks);reach_free(&seenfiles);darc_flat_free(&t);return rc;}
static int published_has(const VSnapVec*s,const DarcCid*c){for(size_t i=0;i<s->n;i++)if(darc_cid_eq(&s->v[i].cid,c))return 1;return 0;}
static int index_check(const char*repo,const DarcDiskList*dl,bool repair,VStat*vs){DarcRhMap m;int rc=darc_index_load(repo,&m);if(rc){vs->index_bad++;vs->degraded=true;if(repair){rc=darc_index_rebuild(repo);if(!rc){vs->repaired++;return 0;}}return repair?rc:0;}bool bad=m.n!=dl->n;for(size_t i=0;i<dl->n&&!bad;i++){DarcRhEnt*e=darc_rh_get(&m,&dl->v[i].cid);if(!e||!dl->v[i].h.used||e->type!=dl->v[i].h.type||e->codec!=dl->v[i].h.codec||e->stored_len!=dl->v[i].h.stored_len||e->uncomp_len!=dl->v[i].h.uncomp_len)bad=true;}darc_rh_free(&m);if(bad){vs->index_bad++;vs->degraded=true;if(repair){rc=darc_index_rebuild(repo);if(!rc)vs->repaired++;return rc;}}return 0;}
static int regenerate_stripe(const char*repo,DarcCatalog*cat,size_t si,const DarcConfig*c,VStat*vs){DarcStripe*st=&cat->v[si];DarcParityMember mm[8];uint8_t*chunks[8]={0};DarcBuf bufs[8];memset(bufs,0,sizeof bufs);for(size_t j=0;j<st->n;j++){mm[j]=st->m[j];DarcObject o;int rc=darc_object_load(repo,&st->m[j].cid,&o,1);if(rc||o.type!=OBJ_CHUNK){if(!rc)darc_object_free(&o);for(size_t k=0;k<j;k++)darc_buf_free(&bufs[k]);return DARC_E_UNRECOVERABLE;}bufs[j]=o.payload;o.payload.data=NULL;chunks[j]=bufs[j].data;darc_object_free(&o);}DarcBuf p;if(darc_parity_build_payload(mm,st->n,chunks,&p)){for(size_t j=0;j<st->n;j++)darc_buf_free(&bufs[j]);return DARC_E_IO;}DarcCid want;darc_object_cid(OBJ_PARITY,p.data,p.len,&want);char*op=darc_object_path(repo,&want);if(op){unlink(op);free(op);}bool nn;uint64_t sb;int rc=darc_object_store(repo,OBJ_PARITY,p.data,p.len,c,&want,&sb,&nn);darc_buf_free(&p);for(size_t j=0;j<st->n;j++)darc_buf_free(&bufs[j]);if(!rc){st->parity_cid=want;vs->repaired++;}return rc;}
static int parity_check(const char*repo,Reach*live,bool repair,const DarcConfig*c,VStat*vs){DarcCatalog cat;int rc=darc_catalog_load(repo,&cat);bool dirty=false;if(rc){vs->parity_bad++;vs->degraded=true;return repair?DARC_E_CORRUPT:0;}for(size_t i=0;i<cat.n;i++){DarcStripe*st=&cat.v[i];DarcObject po;int pr=darc_object_load(repo,&st->parity_cid,&po,1);size_t bad_data=0;for(size_t j=0;j<st->n;j++)if(reach_has(live,&st->m[j].cid)){DarcObject co;int cr=darc_object_load(repo,&st->m[j].cid,&co,1);if(cr||co.type!=OBJ_CHUNK)bad_data++;if(!cr)darc_object_free(&co);}if(pr||po.type!=OBJ_PARITY){if(!pr)darc_object_free(&po);vs->parity_bad++;vs->degraded=true;if(repair&&bad_data==0){rc=regenerate_stripe(repo,&cat,i,c,vs);if(rc)break;dirty=true;}continue;}DarcStripe ps;DarcBuf pb;memset(&pb,0,sizeof pb);if(darc_parity_parse(po.payload.data,po.payload.len,&ps,&pb)||ps.n!=st->n){darc_object_free(&po);darc_buf_free(&pb);vs->parity_bad++;vs->degraded=true;if(repair&&bad_data==0){rc=regenerate_stripe(repo,&cat,i,c,vs);if(rc)break;dirty=true;}continue;}bool same=true;for(size_t j=0;j<st->n;j++)if(!darc_cid_eq(&ps.m[j].cid,&st->m[j].cid)||ps.m[j].len!=st->m[j].len)same=false;darc_buf_free(&pb);darc_object_free(&po);if(!same){vs->parity_bad++;vs->degraded=true;}else if(bad_data<=1)vs->parity_ok++;else{vs->unrecoverable++;rc=DARC_E_UNRECOVERABLE;break;}}if(repair&&dirty&&!rc)rc=darc_catalog_write(repo,&cat);darc_catalog_free(&cat);return rc;}
static int temp_journal_check(const char*repo,bool repair,VStat*vs){const char*dirs[]={"tmp","journal"};for(int di=0;di<2;di++){char*p=darc_path_join(repo,dirs[di]);if(!p)return DARC_E_IO;DIR*d=opendir(p);if(!d){free(p);return DARC_E_IO;}struct dirent*de;while((de=readdir(d)))if(strcmp(de->d_name,".")&&strcmp(de->d_name,"..")){vs->degraded=true;if(repair){char*q=darc_path_join(p,de->d_name);if(q){if(!darc_remove_tree(q))vs->repaired++;free(q);}}}closedir(d);free(p);}return 0;}
static const char*status_name(const VStat*v,bool repair,int rc){if(rc==DARC_E_UNRECOVERABLE||v->unrecoverable)return "UNRECOVERABLE";if(repair&&v->repaired&&!v->corrupt)return "REPAIRED";if(v->degraded||v->corrupt||v->missing||v->index_bad||v->parity_bad)return "DEGRADED-REPAIRABLE";return "HEALTHY";}
static void verify_svg(const VStat*v,const char*status){printf("<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\" width=\"900\" height=\"330\" viewBox=\"0 0 900 330\"><rect width=\"900\" height=\"330\" fill=\"white\"/><text x=\"32\" y=\"48\" font-family=\"sans-serif\" font-size=\"26\">DARC Verify — %s</text><text x=\"32\" y=\"95\" font-family=\"monospace\" font-size=\"16\">objects healthy %llu   corrupt %llu   missing %llu   repaired %llu   unrecoverable %llu</text><text x=\"32\" y=\"130\" font-family=\"monospace\" font-size=\"16\">parity healthy %llu   bad %llu   index bad %llu   history unavailable %llu</text><rect x=\"32\" y=\"175\" width=\"760\" height=\"30\" fill=\"#ddd\"/><rect x=\"32\" y=\"175\" width=\"%llu\" height=\"30\" fill=\"#4a8\"/><text x=\"32\" y=\"255\" font-family=\"sans-serif\" font-size=\"18\">Final status: %s</text></svg>\n",status,(unsigned long long)v->healthy,(unsigned long long)v->corrupt,(unsigned long long)v->missing,(unsigned long long)v->repaired,(unsigned long long)v->unrecoverable,(unsigned long long)v->parity_ok,(unsigned long long)v->parity_bad,(unsigned long long)v->index_bad,(unsigned long long)v->history_missing,(unsigned long long)(v->objects?760*v->healthy/v->objects:0),status);}
static int verify_once(const char*repo,const DarcConfig*c,bool repair,VStat*vs){
 memset(vs,0,sizeof*vs);int rc=darc_repo_check(repo);if(rc)return rc;VSnapVec snaps;rc=read_refs(repo,&snaps,vs);if(rc){if(rc!=DARC_E_UNSUPPORTED)darc_error(DARC_E_CORRUPT,"E_REPO_CORRUPT","snapshot refs/HEAD are invalid");return rc;}Reach live;rc=build_reach(repo,&snaps,&live);if(rc&&rc!=DARC_E_CORRUPT){snaps_free(&snaps);return rc;}if(rc==DARC_E_CORRUPT){snaps_free(&snaps);return rc;}DarcDiskList dl;int lrc=darc_list_objects(repo,&dl,true);if(lrc){reach_free(&live);snaps_free(&snaps);return lrc;}vs->objects=dl.n;for(size_t i=0;i<dl.n;i++){char hx[65];darc_cid_hex(&dl.v[i].cid,hx);if(!dl.v[i].h.used){vs->corrupt++;vs->degraded=true;darc_error(DARC_E_CORRUPT,"E_OBJECT_CORRUPT","object %s has an invalid or truncated frame header",hx);continue;}if(c->verify_level==0){vs->healthy++;continue;}DarcObject o;int x=darc_object_load(repo,&dl.v[i].cid,&o,1);if(x){vs->corrupt++;vs->degraded=true;if(x==DARC_E_UNSUPPORTED&&!rc)rc=DARC_E_UNSUPPORTED;darc_error(x==DARC_E_UNSUPPORTED?DARC_E_UNSUPPORTED:DARC_E_CORRUPT,x==DARC_E_UNSUPPORTED?"E_UNSUPPORTED_OBJECT":"E_OBJECT_CORRUPT","object %s failed full decode/CID verification",hx);}else{vs->healthy++;darc_object_free(&o);}}
 if(index_check(repo,&dl,repair,vs)) rc=DARC_E_CORRUPT;
 if(c->verify_level>=1){for(size_t i=0;i<snaps.n&&rc!=DARC_E_UNRECOVERABLE;i++){if(snaps.v[i].s.has_parent&&!published_has(&snaps,&snaps.v[i].s.parent)){char*pp=darc_object_path(repo,&snaps.v[i].s.parent);struct stat st;if(!pp||stat(pp,&st))vs->history_missing++;free(pp);}int x=verify_snapshot_totals(repo,&snaps.v[i],vs,repair);if(x==DARC_E_UNRECOVERABLE)rc=x;else if(x){vs->degraded=true;if(!rc)rc=DARC_E_CORRUPT;}}}
 if(c->verify_level>=2&&rc!=DARC_E_UNRECOVERABLE){int x=parity_check(repo,&live,repair,c,vs);if(x==DARC_E_UNRECOVERABLE)rc=x;else if(x&&!rc)rc=x;}if(temp_journal_check(repo,repair,vs)&&!rc)rc=DARC_E_IO;if(repair&&vs->repaired&&rc!=DARC_E_UNRECOVERABLE){if(darc_index_rebuild(repo)&&!rc)rc=DARC_E_IO;}
 darc_disklist_free(&dl);reach_free(&live);snaps_free(&snaps);return rc;
}
int darc_cmd_verify(const char*repo,const DarcConfig*c){VStat vs;int rc=verify_once(repo,c,c->verify_repair,&vs);uint64_t repaired=vs.repaired;if(c->verify_repair&&rc!=DARC_E_UNRECOVERABLE&&rc!=DARC_E_UNSUPPORTED){VStat final;int frc=verify_once(repo,c,false,&final);final.repaired=repaired;vs=final;rc=frc;}const char*status=status_name(&vs,c->verify_repair,rc);if(c->verify_repair&&repaired&&!rc)status="REPAIRED";if(c->output_format==3)verify_svg(&vs,status);else if(c->output_format==1)printf("{\"status\":\"%s\",\"objects\":%llu,\"healthy\":%llu,\"corrupt\":%llu,\"missing\":%llu,\"repaired\":%llu,\"unrecoverable\":%llu,\"parity_healthy\":%llu,\"parity_bad\":%llu,\"index_bad\":%llu,\"history_parent_unavailable\":%llu}\n",status,(unsigned long long)vs.objects,(unsigned long long)vs.healthy,(unsigned long long)vs.corrupt,(unsigned long long)vs.missing,(unsigned long long)vs.repaired,(unsigned long long)vs.unrecoverable,(unsigned long long)vs.parity_ok,(unsigned long long)vs.parity_bad,(unsigned long long)vs.index_bad,(unsigned long long)vs.history_missing);else if(c->output_format==2)printf("{\"record\":\"summary\",\"status\":\"%s\",\"healthy\":%llu,\"corrupt\":%llu,\"missing\":%llu,\"repaired\":%llu,\"unrecoverable\":%llu}\n",status,(unsigned long long)vs.healthy,(unsigned long long)vs.corrupt,(unsigned long long)vs.missing,(unsigned long long)vs.repaired,(unsigned long long)vs.unrecoverable);else printf("Repository metadata: refs=%llu history-parent-unavailable=%llu\nCanonical objects: total=%llu healthy=%llu corrupt=%llu missing=%llu\nMerkle/content: %s\nParity: healthy=%llu bad=%llu\nIndex: %s\nRepair actions: %llu\nFinal result: %s\n",(unsigned long long)vs.refs,(unsigned long long)vs.history_missing,(unsigned long long)vs.objects,(unsigned long long)vs.healthy,(unsigned long long)vs.corrupt,(unsigned long long)vs.missing,rc==DARC_E_UNRECOVERABLE?"UNRECOVERABLE":"checked",(unsigned long long)vs.parity_ok,(unsigned long long)vs.parity_bad,vs.index_bad?"INCONSISTENT":"consistent",(unsigned long long)vs.repaired,status);if(!rc&&(!strcmp(status,"HEALTHY")||!strcmp(status,"REPAIRED")))return 0;if(rc==DARC_E_UNRECOVERABLE||!strcmp(status,"UNRECOVERABLE"))return DARC_E_UNRECOVERABLE;if(rc==DARC_E_UNSUPPORTED)return DARC_E_UNSUPPORTED;return DARC_E_CORRUPT;}

/* Rebuild the active parity layout deterministically for a sorted set of live chunks. */
static int cid_sort(const void*a,const void*b){return darc_cid_cmp((const DarcCid*)a,(const DarcCid*)b);}
static int rebuild_live_parity(const char*repo,Reach*live,const DarcConfig*c,DarcCatalog*out){memset(out,0,sizeof*out);DarcCid*ids=darc_malloc((live->n?live->n:1)*sizeof*ids);if(!ids)return DARC_E_IO;size_t n=0;for(size_t i=0;i<live->n;i++){DarcRhEnt*e=darc_rh_get(&live->map,&live->order[i]);if(e&&e->type==OBJ_CHUNK)ids[n++]=live->order[i];}if(n>1)qsort(ids,n,sizeof*ids,cid_sort);for(size_t base=0;base<n;base+=8){size_t k=n-base<8?n-base:8;DarcParityMember m[8];uint8_t*chunks[8]={0};DarcBuf bufs[8];memset(bufs,0,sizeof bufs);int rc=0;for(size_t j=0;j<k;j++){DarcObject o;rc=darc_object_load(repo,&ids[base+j],&o,1);if(rc||o.type!=OBJ_CHUNK){if(!rc)darc_object_free(&o);rc=DARC_E_CORRUPT;break;}m[j].cid=ids[base+j];m[j].len=o.payload.len;bufs[j]=o.payload;o.payload.data=NULL;chunks[j]=bufs[j].data;darc_object_free(&o);}if(rc){for(size_t j=0;j<k;j++)darc_buf_free(&bufs[j]);free(ids);darc_catalog_free(out);return rc;}DarcBuf p;if(darc_parity_build_payload(m,k,chunks,&p)){for(size_t j=0;j<k;j++)darc_buf_free(&bufs[j]);free(ids);darc_catalog_free(out);return DARC_E_IO;}DarcCid pc;bool nn;uint64_t sb;rc=darc_object_store(repo,OBJ_PARITY,p.data,p.len,c,&pc,&sb,&nn);darc_buf_free(&p);for(size_t j=0;j<k;j++)darc_buf_free(&bufs[j]);if(rc){free(ids);darc_catalog_free(out);return rc;}if(out->n==out->cap){size_t nc=out->cap?out->cap*2:16;DarcStripe*v=darc_realloc(out->v,nc*sizeof*v);if(!v){free(ids);darc_catalog_free(out);return DARC_E_IO;}out->v=v;out->cap=nc;}DarcStripe*st=&out->v[out->n++];memset(st,0,sizeof*st);st->parity_cid=pc;st->n=k;for(size_t j=0;j<k;j++)st->m[j]=m[j];}free(ids);return 0;}
static int tx_gc_begin(const char*repo,char**tx){char rel[128];struct timespec ts;clock_gettime(CLOCK_REALTIME,&ts);snprintf(rel,sizeof rel,"journal/%lld-%ld-gc",(long long)ts.tv_sec,(long)getpid());*tx=darc_path_join(repo,rel);if(!*tx||darc_mkdir_p(*tx,0755))return -1;char*p=darc_path_join(*tx,"state");if(!p||darc_atomic_write(p,"planned\n",8,0644)){free(p);return -1;}free(p);return 0;}
int darc_cmd_gc(const char*repo,const DarcConfig*c){VSnapVec snaps;VStat dummy;memset(&dummy,0,sizeof dummy);int rc=read_refs(repo,&snaps,&dummy);if(rc)return rc;Reach live;rc=build_reach(repo,&snaps,&live);if(rc){snaps_free(&snaps);return rc;}DarcCatalog old;rc=darc_catalog_load(repo,&old);if(rc){reach_free(&live);snaps_free(&snaps);return DARC_E_CORRUPT;}bool parity_change=false;if(!c->gc_repack_parity){for(size_t i=0;i<old.n;i++){bool any=false;for(size_t j=0;j<old.v[i].n;j++)if(reach_has(&live,&old.v[i].m[j].cid))any=true;if(any){reach_add(&live,&old.v[i].parity_cid,OBJ_PARITY);for(size_t j=0;j<old.v[i].n;j++)reach_add(&live,&old.v[i].m[j].cid,OBJ_CHUNK);}}}else{for(size_t i=0;i<old.n;i++){bool all=true;for(size_t j=0;j<old.v[i].n;j++)if(!reach_has(&live,&old.v[i].m[j].cid)){all=false;break;}if(all)reach_add(&live,&old.v[i].parity_cid,OBJ_PARITY);else parity_change=true;}}DarcDiskList dl;rc=darc_list_objects(repo,&dl,false);if(rc){darc_catalog_free(&old);reach_free(&live);snaps_free(&snaps);return rc;}uint64_t unreachable=0,bytes=0;for(size_t i=0;i<dl.n;i++)if(!reach_has(&live,&dl.v[i].cid)){unreachable++;bytes+=dl.v[i].h.stored_len+36;}if(c->gc_dry_run){printf("GC dry-run (NO CHANGES)\n  reachable objects: %zu\n  unreachable objects: %llu\n  reclaimable stored bytes: %llu\n  parity stripes to rewrite/drop: %s\n  parity policy: %s\n  mutations: 0\n",live.n,(unsigned long long)unreachable,(unsigned long long)bytes,parity_change?"one or more":"0",c->gc_repack_parity?"repack affected stripes":"retain whole live stripes");darc_disklist_free(&dl);darc_catalog_free(&old);reach_free(&live);snaps_free(&snaps);return 0;}int lock;rc=darc_lock_acquire(repo,&lock);if(rc)goto out;char*tx=NULL;if(tx_gc_begin(repo,&tx)){rc=DARC_E_IO;darc_lock_release(repo,lock);goto out;}DarcCatalog neu;memset(&neu,0,sizeof neu);if(c->gc_repack_parity&&parity_change){/* Rebuild only when at least one active stripe has a dead member (or is entirely stale). */
 darc_checkpoint("gc_before_replacement_parity");rc=rebuild_live_parity(repo,&live,c,&neu);if(rc)goto gc_fail;darc_checkpoint("gc_before_catalog_replace");rc=darc_catalog_write(repo,&neu);if(rc)goto gc_fail;for(size_t i=0;i<neu.n;i++)reach_add(&live,&neu.v[i].parity_cid,OBJ_PARITY);
 }else {neu=old;memset(&old,0,sizeof old);}darc_checkpoint("gc_after_replacement_parity");uint64_t removed=0,removed_bytes=0;for(size_t i=0;i<dl.n;i++)if(!reach_has(&live,&dl.v[i].cid)){if(unlink(dl.v[i].path)&&errno!=ENOENT){rc=DARC_E_IO;goto gc_fail;}removed++;removed_bytes+=dl.v[i].h.stored_len+36;darc_checkpoint("gc_during_delete");}if(darc_index_rebuild(repo)){rc=DARC_E_IO;goto gc_fail;}darc_checkpoint("gc_after_index");(void)darc_remove_tree(tx);free(tx);tx=NULL;printf("GC complete\n  reachable objects: %zu\n  removed objects: %llu\n  reclaimed stored bytes: %llu\n  parity stripes active: %zu\n",live.n,(unsigned long long)removed,(unsigned long long)removed_bytes,neu.n);rc=0;gc_fail:if(tx)free(tx);darc_catalog_free(&neu);darc_lock_release(repo,lock);out:darc_disklist_free(&dl);darc_catalog_free(&old);reach_free(&live);snaps_free(&snaps);return rc;}

int darc_cmd_stats(const char*repo,const DarcConfig*c){VSnapVec snaps;VStat vs;memset(&vs,0,sizeof vs);int rc=read_refs(repo,&snaps,&vs);if(rc)return rc;DarcDiskList dl;rc=darc_list_objects(repo,&dl,false);if(rc){snaps_free(&snaps);return rc;}uint64_t cnt[6]={0},chunk_log=0,chunk_stored=0,parity=0;for(size_t i=0;i<dl.n;i++){uint8_t t=dl.v[i].h.type;if(t<=5)cnt[t]++;if(t==OBJ_CHUNK){chunk_log+=dl.v[i].h.uncomp_len;chunk_stored+=dl.v[i].h.stored_len;}if(t==OBJ_PARITY)parity+=dl.v[i].h.stored_len;}uint64_t across=0,headlogical=0;DarcCid head;bool have=false;char*hp=darc_path_join(repo,"HEAD");DarcBuf hb;if(hp&&!darc_read_file(hp,&hb,128)&&hb.len==65){char h[65];memcpy(h,hb.data,64);h[64]=0;if(!darc_hex_cid(h,&head))have=true;darc_buf_free(&hb);}free(hp);for(size_t i=0;i<snaps.n;i++){across+=snaps.v[i].s.logical_bytes;if(have&&darc_cid_eq(&snaps.v[i].cid,&head))headlogical=snaps.v[i].s.logical_bytes;}DarcRhMap idx;size_t cap=0,nidx=0;if(!darc_index_load(repo,&idx)){cap=idx.cap;nidx=idx.n;darc_rh_free(&idx);}uint64_t comp_save=chunk_log>chunk_stored?chunk_log-chunk_stored:0;uint64_t dedup_save=across>chunk_log?across-chunk_log:0;if(c->output_format==3){uint64_t mx=across;if(chunk_log>mx)mx=chunk_log;if(chunk_stored>mx)mx=chunk_stored;if(parity>mx)mx=parity;if(!mx)mx=1;printf("<svg xmlns=\"http://www.w3.org/2000/svg\" version=\"1.1\" width=\"960\" height=\"460\" viewBox=\"0 0 960 460\"><rect width=\"960\" height=\"460\" fill=\"white\"/><text x=\"32\" y=\"45\" font-family=\"sans-serif\" font-size=\"26\">DARC Repository Statistics</text><text x=\"32\" y=\"80\" font-family=\"monospace\" font-size=\"15\">snapshots %zu   objects %zu   HEAD logical %llu bytes</text>",snaps.n,dl.n,(unsigned long long)headlogical);const char*lab[]={"logical across snapshots","unique chunk bytes","compressed chunk bytes","parity overhead"};uint64_t val[]={across,chunk_log,chunk_stored,parity};for(int i=0;i<4;i++){double w=580.0*(double)val[i]/(double)mx;printf("<text x=\"32\" y=\"%d\" font-family=\"sans-serif\" font-size=\"14\">%s — %llu</text><rect x=\"340\" y=\"%d\" width=\"%.2f\" height=\"22\" fill=\"#579\"/>",130+i*62,lab[i],(unsigned long long)val[i],112+i*62,w);}printf("<text x=\"32\" y=\"395\" font-family=\"sans-serif\" font-size=\"15\">compression savings %.2f%%   cross-snapshot dedup savings %.2f%%</text></svg>\n",chunk_log?100.0*(double)comp_save/(double)chunk_log:0.0,across?100.0*(double)dedup_save/(double)across:0.0);}else if(c->output_format==1)printf("{\"snapshots\":%zu,\"objects\":{\"chunk\":%llu,\"file\":%llu,\"tree\":%llu,\"snapshot\":%llu,\"parity\":%llu},\"head_logical_bytes\":%llu,\"logical_bytes_across_snapshots\":%llu,\"unique_chunk_logical_bytes\":%llu,\"stored_chunk_bytes\":%llu,\"compression_savings_bytes\":%llu,\"dedup_savings_bytes\":%llu,\"parity_overhead_bytes\":%llu,\"index_entries\":%zu,\"index_capacity\":%zu}\n",snaps.n,(unsigned long long)cnt[1],(unsigned long long)cnt[2],(unsigned long long)cnt[3],(unsigned long long)cnt[4],(unsigned long long)cnt[5],(unsigned long long)headlogical,(unsigned long long)across,(unsigned long long)chunk_log,(unsigned long long)chunk_stored,(unsigned long long)comp_save,(unsigned long long)dedup_save,(unsigned long long)parity,nidx,cap);else if(c->output_format==2)printf("{\"record\":\"summary\",\"snapshots\":%zu,\"objects\":%zu,\"head_logical_bytes\":%llu,\"stored_chunk_bytes\":%llu}\n",snaps.n,dl.n,(unsigned long long)headlogical,(unsigned long long)chunk_stored);else printf("Snapshots: %zu\nObjects: chunk=%llu file=%llu tree=%llu snapshot=%llu parity=%llu\nLogical HEAD: %llu bytes\nLogical across snapshots: %llu bytes\nUnique chunk logical: %llu bytes\nStored chunk bytes: %llu bytes\nCompression savings: %llu bytes\nCross-snapshot dedup savings: %llu bytes\nParity overhead: %llu bytes\nIndex: %zu/%zu (%.1f%% load)\nFormat: v1 sha256 buzhash64 lzh1 xor8+1\n",snaps.n,(unsigned long long)cnt[1],(unsigned long long)cnt[2],(unsigned long long)cnt[3],(unsigned long long)cnt[4],(unsigned long long)cnt[5],(unsigned long long)headlogical,(unsigned long long)across,(unsigned long long)chunk_log,(unsigned long long)chunk_stored,(unsigned long long)comp_save,(unsigned long long)dedup_save,(unsigned long long)parity,nidx,cap,cap?100.0*(double)nidx/(double)cap:0.0);darc_disklist_free(&dl);snaps_free(&snaps);return 0;}
int darc_cmd_repo_inspect(const char*repo,const DarcConfig*c){int rc=darc_repo_check(repo);if(rc)return rc;VSnapVec snaps;VStat vs;memset(&vs,0,sizeof vs);rc=read_refs(repo,&snaps,&vs);if(rc)return rc;DarcDiskList dl;rc=darc_list_objects(repo,&dl,true);if(rc){snaps_free(&snaps);return rc;}DarcRhMap idx;int ir=darc_index_load(repo,&idx);size_t in=0,ic=0;if(!ir){in=idx.n;ic=idx.cap;darc_rh_free(&idx);}if(c->output_format==1)printf("{\"format\":1,\"snapshots\":%zu,\"objects\":%zu,\"index_ok\":%s,\"index_entries\":%zu,\"index_capacity\":%zu}\n",snaps.n,dl.n,ir?"false":"true",in,ic);else printf("DARC repository: %s\nFormat: 1 (sha256 / buzhash64 / lzh1 / xor8+1)\nPublished snapshots: %zu\nCanonical objects: %zu\nIndex: %s (%zu/%zu)\n",repo,snaps.n,dl.n,ir?"CORRUPT/MISSING":"OK",in,ic);darc_disklist_free(&dl);snaps_free(&snaps);return 0;}
